<?php $title='Gestão de hotel pet friendly'; ?>
<div class="dashboard-grid two"><section class="panel-card"><h2>Novo espaço de hospedagem</h2><form method="post" action="<?=url('/partner/hotel/units')?>"><?=csrf_field()?><label>Nome<input name="name" required></label><div class="form-grid"><label>Capacidade<input type="number" name="capacity" value="1"></label><label>Portes aceitos<input name="pet_size" placeholder="Pequeno e médio"></label></div><label>Diária (R$)<input type="number" step="0.01" name="daily_price"></label><label>Descrição<textarea name="description" rows="4"></textarea></label><button class="btn btn-primary btn-block">Adicionar espaço</button></form></section><section class="panel-card"><h2>Unidades</h2><?php foreach($units as $unit):?><div class="service-admin"><div><b><?=e($unit['name'])?></b><p><?=e($unit['description'])?></p><small>Capacidade <?=e($unit['capacity'])?> · <?=e($unit['pet_size'])?></small></div><strong><?=money($unit['daily_price_cents'])?>/dia</strong></div><?php endforeach;?></section></div>
<section class="dashboard-section"><h2>Hospedagens</h2><div class="table-wrap"><table><thead><tr><th>Pet</th><th>Família</th><th>Unidade</th><th>Período</th><th>Requisitos</th><th>Gestão</th></tr></thead><tbody><?php foreach($bookings as $item):?><tr><td><?=e($item['pet_name'])?></td><td><?=e($item['owner_name'])?></td><td><?=e($item['unit_name'])?></td><td><?=e($item['check_in'])?> a <?=e($item['check_out'])?></td><td><?=$item['requirements_checked']?'✓ conferidos':'Pendentes'?></td><td><form method="post" action="<?=url('/partner/hotel/bookings/'.$item['id'])?>" class="inline-form"><?=csrf_field()?><select name="status"><?php foreach(['PENDING','CONFIRMED','CHECKED_IN','COMPLETED','CANCELLED'] as $status):?><option <?=selected($item['status'],$status)?>><?=$status?></option><?php endforeach;?></select><label class="check compact"><input type="checkbox" name="requirements_checked" value="1" <?=checked($item['requirements_checked'])?>> Vacinas e requisitos</label><button class="btn btn-soft">Salvar</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
